from app.api.handlers import handle_user_exists

def test_handle_user_exists_success():
    # User 1 exists
    params = {"id": "1"}
    status, response = handle_user_exists(params)
    assert status == 200
    assert response == {"exists": True}

    # User 3 does not exist
    params = {"id": "3"}
    status, response = handle_user_exists(params)
    assert status == 200
    assert response == {"exists": False}

def test_handle_user_exists_invalid_params():
    # Missing ID
    params = {}
    status, response = handle_user_exists(params)
    assert status == 400
    assert response == {"error": "invalid id"}

    # Non-string ID
    params = {"id": 1}
    status, response = handle_user_exists(params)
    assert status == 400
    assert response == {"error": "invalid id"}

    # Non-digit string ID
    params = {"id": "a"}
    status, response = handle_user_exists(params)
    assert status == 400
    assert response == {"error": "invalid id"}
", "path": "tests/test_handlers.py"}

